/*
∑_i α_i + 1/M ∑_i ∑_j (f(X_i,j)/`p_c`(X_i,j) - (∑_k α_k p_k X_i,j)/`p_c`(X_i,j))
        where
        α: ℝ^m
        p: ℝ^m
        X: ℝ^(m×n)
        M: ℝ
        f: ℝ -> ℝ
        `p_c`: ℝ -> ℝ 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT ret;

    heartlib(
        const Eigen::VectorXd & α,
        const Eigen::VectorXd & p,
        const Eigen::MatrixXd & X,
        const double & M,
        const std::function<double(double)> & f,
        const std::function<double(double)> & p_c)
    {
        const long m = α.size();
        const long n = X.cols();
        assert( p.size() == m );
        assert( X.rows() == m );
        DT sum_0 = 0;
        for(int i=1; i<=α.size(); i++){
            sum_0 += α[i-1];
        }
        DT sum_1 = 0;
        for(int i=1; i<=X.rows(); i++){
            DT sum_2 = 0;
            for(int j=1; j<=X.cols(); j++){
                DT sum_3 = 0;
                for(int k=1; k<=p.size(); k++){
                    sum_3 += α[k-1] * p[k-1] * X(i-1, j-1);
                }
                sum_2 += (f(X(i-1, j-1)) / DT(p_c(X(i-1, j-1))) - (sum_3) / DT(p_c(X(i-1, j-1))));
            }
            sum_1 += sum_2;
        }
        ret = sum_0 + 1 / DT(M) * sum_1;
    }
};

