function output = heartlib(alpha, p, X, M, f, p_c)
% output = heartlib(α, p, X, M, f, `p_c`)
%
%    ∑_i α_i + 1/M ∑_i ∑_j (f(X_i,j)/`p_c`(X_i,j) - (∑_k α_k p_k X_i,j)/`p_c`(X_i,j))
%            where
%            α: ℝ^m
%            p: ℝ^m
%            X: ℝ^(m×n)
%            M: ℝ
%            f: ℝ -> ℝ
%            `p_c`: ℝ -> ℝ 
    alpha = reshape(alpha,[],1);
    p = reshape(p,[],1);

    m = size(alpha, 1);
    n = size(X, 2);
    assert( numel(alpha) == m );
    assert( numel(p) == m );
    assert( isequal(size(X), [m, n]) );
    assert(numel(M) == 1);

    sum_0 = 0;
    for i = 1:size(alpha,1)
        sum_0 = sum_0 + alpha(i);
    end
    sum_1 = 0;
    for i = 1:size(X,1)
        sum_2 = 0;
        for j = 1:size(X,2)
            sum_3 = 0;
            for k = 1:size(p,1)
                sum_3 = sum_3 + alpha(k) * p(k) * X(i, j);
            end
            sum_2 = sum_2 + (f(X(i, j)) / p_c(X(i, j)) - (sum_3) / p_c(X(i, j)));
        end
        sum_1 = sum_1 + sum_2;
    end
    ret = sum_0 + 1 / M * sum_1;
    output.ret = ret;
end

